 public static function key(string$s):string{return'xinvoice_'.substr(hash('sha256',$s),0,24);}
 public static function messages(string$locale):array{$en=explode('-',$locale,2)[0]==='en';$out=[];foreach(self::ENGLISH as$s=>$v)$out[self::key($s)]=$en?$v:$s;return$out;}
 public static function text(string$s,array$messages,array$values=[]):string{
  if(!isset($messages[self::key($s)])){
   if(preg_match('/\ABitte das Feld „([^“]+)“ ausfüllen bzw\. prüfen \(höchstens ([0-9]+) Zeichen, keine Zeilenumbrüche\)\.\z/u',$s,$m)&&isset(self::ENGLISH[$m[1]]))return self::text('Bitte das Feld „{field}“ ausfüllen bzw. prüfen (höchstens {limit} Zeichen, keine Zeilenumbrüche).',$messages,['field'=>self::text($m[1],$messages),'limit'=>$m[2]]);
   if(preg_match('/\ABitte das Feld „([^“]+)“ als gültige E-Mail-Adresse eingeben\.\z/u',$s,$m)&&isset(self::ENGLISH[$m[1]]))return self::text('Bitte das Feld „{field}“ als gültige E-Mail-Adresse eingeben.',$messages,['field'=>self::text($m[1],$messages)]);
  }
  return strtr($messages[self::key($s)]??$s,array_combine(array_map(static fn($k)=>'{'.$k.'}',array_keys($values)),array_values($values)));
 }
